def layout(words, seed):
    rng=random.Random(seed); best=None
    for trial in range(250):
        ordered=list(words);rng.shuffle(ordered)
        if trial==0: ordered.sort(key=lambda x:-len(x[0]))
        grid={};axes={};placed=[]
        for answer,clue in ordered:
            candidates=[]
            if not grid:candidates=[(0,0,'across',0)]
            else:
                for (r,c),letter in list(grid.items()):
                    for i,a in enumerate(answer):
                        if a!=letter:continue
                        for direction in ['across','down']:
                            dr=int(direction=='down');dc=1-dr;rr=r-dr*i;cc=c-dc*i
                            if (rr-dr,cc-dc) in grid or (rr+dr*len(answer),cc+dc*len(answer)) in grid:continue
                            score=0;valid=True
                            for j,ch in enumerate(answer):
                                pos=(rr+dr*j,cc+dc*j)
                                if pos in grid:
                                    if grid[pos]!=ch or direction in axes[pos]:valid=False;break
                                    score+=1
                                elif (pos[0]+dc,pos[1]+dr) in grid or (pos[0]-dc,pos[1]-dr) in grid:valid=False;break
                            if valid:
                                cells=list(grid)+[(rr,cc),(rr+dr*(len(answer)-1),cc+dc*(len(answer)-1))]
                                area=(max(x[0] for x in cells)-min(x[0] for x in cells)+1)*(max(x[1] for x in cells)-min(x[1] for x in cells)+1)
                                candidates.append((rr,cc,direction,score*100-area+rng.random()*10))
            if not candidates:continue
            r,c,direction,_=max(candidates,key=lambda x:x[3]);dr=int(direction=='down');dc=1-dr
            for j,ch in enumerate(answer):pos=(r+dr*j,c+dc*j);grid[pos]=ch;axes.setdefault(pos,set()).add(direction)
            placed.append(dict(answer=answer,clue=clue,row=r,col=c,direction=direction,length=len(answer)))
        area=(max(r for r,c in grid)-min(r for r,c in grid)+1)*(max(c for r,c in grid)-min(c for r,c in grid)+1)
        rank=(len(placed),-area)
        if best is None or rank>best[0]:best=(rank,placed,grid)
    _,placed,grid=best
    minr=min(r for r,c in grid);minc=min(c for r,c in grid)
    grid={(r-minr,c-minc):v for (r,c),v in grid.items()}
    for cl in placed:cl['row']-=minr;cl['col']-=minc
    starts=sorted(set((cl['row'],cl['col']) for cl in placed))
    for cl in placed:cl['number']=starts.index((cl['row'],cl['col']))+1;cl['id']=f"{cl['number']}-{cl['direction']}"
    placed.sort(key=lambda cl:(cl['direction']!='across',cl['number']))
    rows=max(r for r,c in grid)+1;cols=max(c for r,c in grid)+1
    return placed,dict(rows=rows,cols=cols,blocked=[[r,c] for r in range(rows) for c in range(cols) if (r,c) not in grid])

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--count',type=int,default=3);args=parser.parse_args()
    target=Path(__file__).resolve().parents[1]/'data/puzzles';target.mkdir(parents=True,exist_ok=True);index=[]
    for i,(title,category,words) in enumerate(COLLECTIONS[:args.count],1):
        clues,grid=layout(words,i*47)
        if len(clues)<6:raise ValueError(f'Too few entries in {title}')
        difficulty='easy' if i<=4 else 'medium' if i<=16 else 'hard'
        p=dict(schemaVersion=1,id=f'original-{i:03d}',title=title,source=dict(website=None,url=None,sourceId=None,type='original',license='CC0-1.0',author='კროსვორდი'),extractedAt=None,createdAt='2026-11-10',difficulty=difficulty,category=category,grid=grid,clues=clues)
        (target/f"{p['id']}.json").write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
        index.append({k:p[k] for k in ['id','title','difficulty','category']}|dict(rows=grid['rows'],cols=grid['cols'],clueCount=len(clues),cellCount=grid['rows']*grid['cols']-len(grid['blocked']),sourceType='original',estimatedMinutes=6 if difficulty=='easy' else 12 if difficulty=='medium' else 20))
    (target/'index.json').write_text(json.dumps(dict(schemaVersion=1,catalogVersion='originals-2026-11-10',calendarBasis='Asia/Tbilisi',puzzles=index),ensure_ascii=False,indent=2)+'\n')
    print(f'Created {len(index)} original puzzles.')
if __name__=='__main__':main()
